using System;
using System.Collections.Generic;

namespace SeaGlass.Core;

/// <summary>
/// 2D Signed Distance Field (SDF) primitive, smooth-minimum (<c>sminCubic</c>) coalescing,
/// and analytical bevel normal evaluator for SeaGlass.
///
/// Exact 1:1 mathematical parity with <c>dev.seaglass.core.SeaGlassSdfEngine</c> on Android
/// and all GPU shader dialects generated by <see cref="Backend.SeaGlassShaderCompiler"/>.
/// </summary>
public static class SeaGlassSdfEngine
{
    /// <summary>
    /// Maximum number of coalescing SDF nodes evaluated per local cluster in a single GPU pass.
    /// Kept at 4 so every node fits in a single 256-byte <c>cbuffer</c> / <c>std140</c> uniform block.
    /// </summary>
    public const int MaxSdfNodes = 4;

    /// <summary>
    /// Single 2D expressive shape node in pixel coordinates relative to the render target origin.
    /// </summary>
    public readonly record struct SdfNode(
        float CenterX,
        float CenterY,
        float HalfWidth,
        float HalfHeight,
        float CornerTopRight,
        float CornerBottomRight,
        float CornerBottomLeft,
        float CornerTopLeft,
        float CornerSmoothing = 2.45f,
        int TintColorArgb = unchecked((int)0xFF6EE7C8),
        float ThicknessPx = 28f,
        SeaGlassShapeKind? StartShapeKind = null,
        SeaGlassShapeKind? EndShapeKind = null,
        float ShapeMorphProgress = 0f)
    {
        public SdfNode(
            float centerX,
            float centerY,
            float halfWidth,
            float halfHeight,
            float uniformCornerRadius,
            float cornerSmoothing = 2.45f,
            int tintColorArgb = unchecked((int)0xFF6EE7C8),
            float thicknessPx = 28f,
            SeaGlassShapeKind? startShapeKind = null,
            SeaGlassShapeKind? endShapeKind = null,
            float shapeMorphProgress = 0f)
            : this(
                CenterX: centerX,
                CenterY: centerY,
                HalfWidth: halfWidth,
                HalfHeight: halfHeight,
                CornerTopRight: uniformCornerRadius,
                CornerBottomRight: uniformCornerRadius,
                CornerBottomLeft: uniformCornerRadius,
                CornerTopLeft: uniformCornerRadius,
                CornerSmoothing: cornerSmoothing,
                TintColorArgb: tintColorArgb,
                ThicknessPx: thicknessPx,
                StartShapeKind: startShapeKind,
                EndShapeKind: endShapeKind,
                ShapeMorphProgress: shapeMorphProgress)
        {
        }
    }

    /// <summary>
    /// Result of evaluating a multi-node coalescing SDF scene at a 2D pixel coordinate <c>(px, py)</c>.
    /// </summary>
    public readonly record struct SdfEvaluation(
        float SignedDistancePx,
        float GradX,
        float GradY,
        float EdgeBevelFactor,
        float NormalX,
        float NormalY,
        float NormalZ,
        int BlendedTintArgb,
        float BlendedThicknessPx)
    {
        public bool IsInside => SignedDistancePx <= 0f;
    }

    /// <summary>
    /// Evaluates the signed distance from <c>(px, py)</c> to an expressive rounded box / squircle
    /// or morphing polygon <paramref name="node"/>.
    /// Negative values are inside the shape, zero is on the boundary, positive values are outside.
    /// </summary>
    public static float EvaluateNodeSdf(float px, float py, SdfNode node)
    {
        float dx = px - node.CenterX;
        float dy = py - node.CenterY;

        if (node.StartShapeKind is { } sKind)
        {
            SeaGlassShapeKind eKind = node.EndShapeKind ?? sKind;
            float angle = MathF.Atan2(dy, dx);
            float polarScale = SeaGlassShapeMorph.EvaluatePolarRadiusScale(
                startKind: sKind,
                endKind: eKind,
                progress: node.ShapeMorphProgress,
                angleRad: angle
            );
            float rx = MathF.Max(2f, node.HalfWidth * polarScale);
            float ry = MathF.Max(2f, node.HalfHeight * polarScale);
            float nx = dx / rx;
            float ny = dy / ry;
            float normDist = MathF.Sqrt(nx * nx + ny * ny);
            float avgR = MathF.Min(rx, ry);
            return (normDist - 1f) * avgR;
        }

        float rRight = dy > 0f ? node.CornerBottomRight : node.CornerTopRight;
        float rLeft = dy > 0f ? node.CornerBottomLeft : node.CornerTopLeft;
        float rawRadius = dx > 0f ? rRight : rLeft;
        float maxRadius = MathF.Max(0f, MathF.Min(node.HalfWidth, node.HalfHeight) * 1.65f);
        float r = Math.Clamp(rawRadius, 0f, maxRadius);

        float qx = MathF.Abs(dx) - node.HalfWidth + r;
        float qy = MathF.Abs(dy) - node.HalfHeight + r;

        float outsideX = MathF.Max(qx, 0f);
        float outsideY = MathF.Max(qy, 0f);
        float insideDist = MathF.Min(MathF.Max(qx, qy), 0f);
        float cornerNorm = MathF.Sqrt(outsideX * outsideX + outsideY * outsideY);

        return insideDist + cornerNorm - r;
    }

    /// <summary>
    /// Inigo Quilez's C^2-continuous cubic polynomial smooth minimum (<c>smin</c>).
    /// Smoothly coalesces two signed distances <paramref name="da"/> and <paramref name="db"/>
    /// over a bridge radius <paramref name="k"/> &gt; 0.
    /// </summary>
    public static float SminCubic(float da, float db, float k)
    {
        if (k <= 0.0001f) return MathF.Min(da, db);
        float h = MathF.Max(k - MathF.Abs(da - db), 0f) / k;
        return MathF.Min(da, db) - h * h * h * k * (1f / 6f);
    }

    /// <summary>
    /// Computes the smooth material interpolation weight in [0f..1f] when coalescing
    /// field <paramref name="da"/> (weight 0) and field <paramref name="db"/> (weight 1)
    /// with smoothness radius <paramref name="k"/>.
    /// </summary>
    public static float SminBlendWeight(float da, float db, float k)
    {
        if (k <= 0.0001f) return da <= db ? 0f : 1f;
        float h = Math.Clamp(MathF.Max(k - MathF.Abs(da - db), 0f) / k, 0f, 1f);
        float m = h * h * 0.5f;
        return da < db ? m : 1f - m;
    }

    /// <summary>
    /// Evaluates a multi-node coalescing scene at <c>(px, py)</c> including analytical gradient,
    /// tumbled edge bevel normal, and Oklab-blended tint across coalescing droplets.
    /// </summary>
    public static SdfEvaluation EvaluateScene(
        float px,
        float py,
        IReadOnlyList<SdfNode> nodes,
        float smoothRadiusPx,
        float bevelWidthPx = 24f)
    {
        if (nodes is null || nodes.Count == 0)
            throw new ArgumentException("nodes must not be empty", nameof(nodes));

        int count = Math.Min(nodes.Count, MaxSdfNodes);
        float combinedDist = EvaluateNodeSdf(px, py, nodes[0]);
        int blendedTint = nodes[0].TintColorArgb;
        float blendedThickness = nodes[0].ThicknessPx;

        for (int i = 1; i < count; i++)
        {
            SdfNode node = nodes[i];
            float dNode = EvaluateNodeSdf(px, py, node);
            float weight = SminBlendWeight(combinedDist, dNode, smoothRadiusPx);
            combinedDist = SminCubic(combinedDist, dNode, smoothRadiusPx);
            if (weight > 0.001f)
            {
                blendedTint = SeaGlassColorMath.LerpOklab(blendedTint, node.TintColorArgb, weight);
                blendedThickness += (node.ThicknessPx - blendedThickness) * weight;
            }
        }

        // Central finite difference for 2D SDF gradient (matches GPU shader step eps = 0.75px)
        const float eps = 0.75f;
        float distXPlus = EvaluateNodeSdf(px + eps, py, nodes[0]);
        float distXMinus = EvaluateNodeSdf(px - eps, py, nodes[0]);
        float distYPlus = EvaluateNodeSdf(px, py + eps, nodes[0]);
        float distYMinus = EvaluateNodeSdf(px, py - eps, nodes[0]);

        for (int i = 1; i < count; i++)
        {
            SdfNode node = nodes[i];
            distXPlus = SminCubic(distXPlus, EvaluateNodeSdf(px + eps, py, node), smoothRadiusPx);
            distXMinus = SminCubic(distXMinus, EvaluateNodeSdf(px - eps, py, node), smoothRadiusPx);
            distYPlus = SminCubic(distYPlus, EvaluateNodeSdf(px, py + eps, node), smoothRadiusPx);
            distYMinus = SminCubic(distYMinus, EvaluateNodeSdf(px, py - eps, node), smoothRadiusPx);
        }

        float rawGx = (distXPlus - distXMinus) / (2f * eps);
        float rawGy = (distYPlus - distYMinus) / (2f * eps);
        float gradLen = MathF.Max(1e-4f, MathF.Sqrt(rawGx * rawGx + rawGy * rawGy));
        float gx = rawGx / gradLen;
        float gy = rawGy / gradLen;

        // Tumbled bevel factor tau in [0f..1f]: 1 at boundary (d = 0), 0 deep in interior
        float safeBevel = MathF.Max(2f, bevelWidthPx);
        float interiorDepth = Math.Clamp((-combinedDist) / safeBevel, 0f, 1f);
        float smoothStep = interiorDepth * interiorDepth * (3f - 2f * interiorDepth);
        float tau = 1f - smoothStep;

        // Reconstruct 3D outward surface normal of the tumbled sea-glass dome
        float nxRaw = gx * tau * 0.85f;
        float nyRaw = gy * tau * 0.85f;
        float nzRaw = MathF.Sqrt(MathF.Max(0.06f, 1f - tau * tau));
        float nLen = MathF.Max(1e-4f, MathF.Sqrt(nxRaw * nxRaw + nyRaw * nyRaw + nzRaw * nzRaw));

        return new SdfEvaluation(
            SignedDistancePx: combinedDist,
            GradX: gx,
            GradY: gy,
            EdgeBevelFactor: tau,
            NormalX: nxRaw / nLen,
            NormalY: nyRaw / nLen,
            NormalZ: nzRaw / nLen,
            BlendedTintArgb: blendedTint,
            BlendedThicknessPx: blendedThickness
        );
    }
}
